import math

def sigmoid(z):
    return 1.0 / (1.0 + math.exp(-z))

print('  z | sigmoid | slope s*(1-s)')
for z in (-6, 0, 6):
    s = sigmoid(z)
    print('%3d |  %.4f  |  %.4f' % (z, s, s * (1 - s)))

print('relu(-3) =', max(0.0, -3.0), ' relu(2.5) =', max(0.0, 2.5))
print('three stacked sigmoids: best-case slope product =',
      round(0.25 * 0.25 * 0.25, 4))
